<?php
$module = $modules[$moduleKey];
$recordId = (int)($_GET['edit'] ?? 0);
$record = [];
if ($recordId > 0) {
    $stmt = $pdo->prepare("SELECT * FROM {$module['table']} WHERE id=?");
    $stmt->execute([$recordId]);
    $record = $stmt->fetch() ?: [];
    if (!$record) { flash('warning','Record not found.'); redirect('index.php?page='.$moduleKey); }
}
$query = trim((string)($_GET['q'] ?? ''));
$where = '';
$params = [];
if ($query !== '') {
    $parts = [];
    foreach (($module['search'] ?? []) as $column) { $parts[] = "CAST({$column} AS CHAR) LIKE ?"; $params[] = '%' . $query . '%'; }
    if ($parts) $where = ' WHERE (' . implode(' OR ',$parts) . ')';
}
$stmt = $pdo->prepare("SELECT * FROM {$module['table']}{$where} ORDER BY id DESC LIMIT 100");
$stmt->execute($params);
$rows = $stmt->fetchAll();
$displayFields = [];
foreach (module_fields($module) as $field) {
    if (in_array($field['type'] ?? 'text',['textarea','password'],true)) continue;
    $displayFields[] = $field;
    if (count($displayFields) >= 6) break;
}
$roleName = current_user()['role_name'] ?? '';
$canDelete = in_array($roleName,['super_admin','hospital_admin'],true) && !($moduleKey === 'users' && $recordId === (int)current_user()['id']);
$alertModule = in_array($moduleKey,['medicines','payments','appointments','admissions','lab_results'],true);
?>
<div class="page-heading"><div><span class="eyebrow text-primary">HOSPITAL OPERATIONS</span><h1><?= e($module['title']) ?></h1><p>Manage <?= strtolower(e($module['title'])) ?> records and keep hospital information up to date.</p></div><div class="heading-actions"><span class="record-count"><i class="fa-solid fa-database me-2"></i><?= number_format(count($rows)) ?> shown</span><a class="btn btn-primary" href="<?= e(url('index.php?page='.$moduleKey)) ?>#record-form"><i class="fa-solid fa-plus me-2"></i>Add new</a></div></div>
<div class="row g-4 align-items-start"><div class="col-12 <?= $recordId || isset($_GET['new']) ? 'col-xxl-8' : '' ?>"><section class="panel-card"><div class="panel-header"><div><h3><?= e($module['title']) ?> directory</h3><p>Search, review, print and update records.</p></div><form class="search-form" method="get"><input type="hidden" name="page" value="<?= e($moduleKey) ?>"><div class="search-input"><i class="fa-solid fa-magnifying-glass"></i><input type="search" name="q" value="<?= e($query) ?>" placeholder="Search records..."></div><button class="btn btn-light" type="submit">Search</button><?php if($query!==''): ?><a class="btn btn-link text-decoration-none" href="<?= e(url('index.php?page='.$moduleKey)) ?>">Clear</a><?php endif; ?></form></div><div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>ID</th><?php foreach($displayFields as $field): ?><th><?= e($field['label']) ?></th><?php endforeach; ?><th class="text-end">Actions</th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="<?= count($displayFields)+2 ?>"><div class="empty-state"><span class="empty-icon"><i class="fa-regular fa-folder-open"></i></span><strong>No matching records</strong><span>Add a new record or change your search query.</span></div></td></tr><?php else: foreach($rows as $row): ?><tr><td><span class="id-badge">#<?= (int)$row['id'] ?></span></td><?php foreach($displayFields as $field): $v = $row[$field['name']] ?? null; ?><td><?php if($field['name']==='status' || $field['name']==='queue_status'): ?><span class="status-pill <?= strtolower(str_replace(' ','-',e((string)$v))) ?>"><?= e($v ?: '—') ?></span><?php else: ?><span class="cell-value"><?= e(format_value($pdo,$field,$v)) ?></span><?php endif; ?></td><?php endforeach; ?><td><div class="table-actions"><a class="action-btn edit" title="Edit" href="<?= e(url('index.php?page='.$moduleKey.'&edit='.(int)$row['id'].'#record-form')) ?>"><i class="fa-regular fa-pen-to-square"></i></a><?php if($moduleKey==='patients'): ?><a class="action-btn print" title="Print patient" target="_blank" href="<?= e(url('index.php?page=print&type=patient&id='.(int)$row['id'])) ?>"><i class="fa-solid fa-print"></i></a><?php elseif($moduleKey==='bills'): ?><a class="action-btn print" title="Print invoice" target="_blank" href="<?= e(url('index.php?page=print&type=bill&id='.(int)$row['id'])) ?>"><i class="fa-solid fa-print"></i></a><?php elseif($moduleKey==='prescriptions'): ?><a class="action-btn print" title="Print prescription" target="_blank" href="<?= e(url('index.php?page=print&type=prescription&id='.(int)$row['id'])) ?>"><i class="fa-solid fa-print"></i></a><?php endif; ?><?php if($canDelete): ?><form method="post" action="<?= e(url('actions.php')) ?>" onsubmit="return confirm('Delete this record? This cannot be undone.');"><?= csrf_field() ?><input type="hidden" name="module" value="<?= e($moduleKey) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="action-btn delete" title="Delete" type="submit"><i class="fa-regular fa-trash-can"></i></button></form><?php endif; ?></div></td></tr><?php endforeach; endif; ?>
</tbody></table></div><div class="table-footnote">Showing up to 100 records. Use search to narrow the list.</div></section></div>
<?php if($recordId || isset($_GET['new'])): ?><div class="col-12 col-xxl-4" id="record-form"><section class="panel-card form-card"><div class="panel-header"><div><h3><?= $recordId ? 'Edit record' : 'Add new record' ?></h3><p>Enter the details below.</p></div><a class="close-form" href="<?= e(url('index.php?page='.$moduleKey)) ?>"><i class="fa-solid fa-xmark"></i></a></div><form method="post" action="<?= e(url('actions.php')) ?>" autocomplete="off" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="module" value="<?= e($moduleKey) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= $recordId ?>">
<?php foreach(module_fields($module) as $field): $fieldValue = $record[$field['name']] ?? ''; if($field['name']==='password') $fieldValue=''; echo field_input($field,$fieldValue,$pdo); if(($field['type']??'')==='file' && !empty($fieldValue)): ?><div class="form-text mb-3">Current file: <a href="<?= e(url((string)$fieldValue)) ?>" target="_blank" rel="noopener">View uploaded file</a></div><?php endif; endforeach; ?>
<div class="form-actions"><a class="btn btn-light" href="<?= e(url('index.php?page='.$moduleKey)) ?>">Cancel</a><button type="submit" class="btn btn-primary"><i class="fa-solid fa-floppy-disk me-2"></i><?= $recordId ? 'Save changes' : 'Create record' ?></button></div></form></section></div><?php else: ?><div class="col-12"><section class="panel-card quick-add"><div class="quick-add-icon"><i class="fa-solid <?= e($module['icon']) ?>"></i></div><div><strong>Need to add a <?= strtolower(e($module['title'])) ?> record?</strong><p>Open the entry form to create a new record. Your changes are saved to the hospital database.</p></div><a class="btn btn-outline-primary ms-auto" href="<?= e(url('index.php?page='.$moduleKey.'&new=1#record-form')) ?>">Open form <i class="fa-solid fa-arrow-right ms-2"></i></a></section></div><?php endif; ?></div>
<?php if($moduleKey==='medicines'): $low=$pdo->query('SELECT medicine_name,quantity,low_stock_threshold,expiry_date FROM medicines WHERE quantity<=low_stock_threshold OR expiry_date<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) ORDER BY quantity LIMIT 8')->fetchAll(); ?><div class="panel-card mt-4"><div class="panel-header"><div><h3>Stock & expiry alerts</h3><p>Items requiring pharmacy team attention</p></div></div><?php if(!$low): ?><div class="empty-state py-3"><span>All medicines are above their stock threshold.</span></div><?php else: ?><div class="table-responsive"><table class="table app-table"><thead><tr><th>Medicine</th><th>Quantity</th><th>Threshold</th><th>Expiry</th></tr></thead><tbody><?php foreach($low as $m): ?><tr><td><?= e($m['medicine_name']) ?></td><td><span class="mini-tag <?= (int)$m['quantity'] <= (int)$m['low_stock_threshold'] ? 'warning':'success' ?>"><?= (int)$m['quantity'] ?></span></td><td><?= (int)$m['low_stock_threshold'] ?></td><td><?= $m['expiry_date'] ? e(date('d M Y',strtotime($m['expiry_date']))) : '—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php endif; ?>
